CREATE TABLE IF NOT EXISTS commercial_records(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),kind TEXT NOT NULL CHECK(kind IN ('rfp','quotation','poc','prospection','opportunity','contract','project')),title TEXT NOT NULL,reference TEXT,stage TEXT NOT NULL DEFAULT 'new' CHECK(stage IN ('new','qualifying','preparing','submitted','negotiation','won','lost','on_hold','in_progress','completed')),value_amount REAL NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'MUR',probability INTEGER NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100),due_date TEXT,owner_id TEXT REFERENCES users(id),notes TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_commercial_customer ON commercial_records(customer_id,kind,stage);CREATE TABLE IF NOT EXISTS commercial_events(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES commercial_records(id),actor_id TEXT NOT NULL REFERENCES users(id),event_type TEXT NOT NULL,detail TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);